const instrArr = getInstrumentsArr("all");
const testDiv = document.createElement("div");
testDiv.innerHTML = instrumentCards("all").join("");
const cards = testDiv.querySelectorAll('div[class="card"]');
assert.lengthOf(cards, 10);
